/* ============================================================ */
/* METİN BİÇİMLENDİRME: SORU KÖKÜ [[ ]] VE ALTI ÇİZİLİ __      */
/* ============================================================ */
function escapeHtml(str) {
  return (str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatQText(raw, stemColor) {
  if (!raw) return '';
  let s = escapeHtml(raw);

  // Soru Kökü [[ ... ]] -> koyu, öncesi ve sonrası boşluklu, yeni satır
  s = s.replace(/\[\[([\s\S]*?)\]\]/g, (match, p1) => {
    const trimmed = p1.trim();
    const styleAttr = stemColor ? ` style="color:${stemColor};"` : '';
    return `\n<div class="q-stem-block"${styleAttr}>${trimmed}</div>\n`;
  });

  // Altı Çizili Metin __...__ -> altı çizgi
  s = s.replace(/__([\s\S]*?)__/g, (match, p1) => {
    return `<span class="q-underline">${p1}</span>`;
  });

  // Satırları böl ve düzenle
  const lines = s.split('\n');
  const out = [];
  lines.forEach(l => {
    const t = l.trim();
    if (!t) return;
    if (t.startsWith('<div class="q-stem-block"') && t.endsWith('</div>')) {
      out.push(t);
    } else {
      out.push(`<div class="qtxt-line">${l}</div>`);
    }
  });

  return out.join('');
}

/* ============================================================ */
/* NÜSHA MODELİ (Soru Bankası & Ders Notu)                      */
/* ============================================================ */
function newDoc(kind) {
  const isNotes = kind === 'Ders Notu';
  return {
    id: uid(),
    title: kind ? kind + ' — Yeni Nüsha' : 'Adsız Nüsha',
    kind: kind || 'Soru Bankası',
    updated: Date.now(),
    cover: { enabled: true, mode: 'color', image: null, showText: true, title: '', subtitle: '', author: 'Sertan Çubukcu', bg: '#6b4426', fg: '#fbf4e8' },
    preface: { enabled: false, title: 'Önsöz', text: '', signature: '', links: [] },
    layout: {
      page: 'A4',
      columns: isNotes ? 1 : 2,
      margin: 14,
      rule: true,
      ruleColor: '#b98a4a', // Ortadaki dikey ayırıcı çizgi rengi
      ruleStyle: 'double',  // 'solid', 'double', 'dashed', 'dotted', 'selcuk', 'chain', 'wave'
      headerText: '',
      footerText: '',
      hfAlign: 'center',
      colHeader: '',
      colFooter: '',
      pageNum: 'center',
      numStyle: '1.',
      // Cevap Anahtarı Tablosu Ayarları
      showAnswerKey: !isNotes,
      answerKeyCols: 5,        // 5 soru / satır
      answerKeyNewPage: false, // sayfa sonu veya yeni sayfa
      answerKeyFontSize: 9.5,  // pt
      // Çözümler Ayarları
      showSolutions: !isNotes,
      solutionsNewPage: false, // çözümler yeni sayfada başlasın
      solutionsFontSize: 10,   // pt
      solutionsLineHeight: 1.5,
    },
    type: { font: 'lora', size: isNotes ? 11 : 10.5, color: '#1d1a17', accent: '#6b4426', stemColor: '#6b4426', leading: 1.5, qGap: isNotes ? 6 : 4 },
    watermark: { enabled: false, kind: 'text', text: 'PITRAK NÜSHA', image: null, imageWidth: 40, opacity: 12, angle: -30, size: 26, color: '#6b4426' },
    items: [],
  };
}

function newQuestion() {
  return {
    id: uid(),
    t: 'q',
    text: '',
    stem: '',     // Soru kökü (ayrı alan)
    image: null,
    w: 0,
    h: 0,
    opts: ['', '', '', '', ''],
    answer: '',   // Doğru cevap: 'A', 'B', 'C', 'D', 'E' veya serbest metin
    explain: ''   // Ayrıntılı soru çözümü
  };
}

function newNote(style = 'info') { return { id: uid(), t: 'note', style, title: '', text: '' }; }
function newHeading() { return { id: uid(), t: 'h', text: '' }; }

const isBlank = it => {
  if (it.t === 'q') {
    const hasText = !!(it.text || '').trim();
    const hasStem = !!(it.stem || '').trim();
    const hasImg = !!it.image;
    const hasAns = !!(it.answer || '').trim();
    const hasExp = !!(it.explain || '').trim();
    const hasOpts = !!(it.opts && it.opts.some(o => (o || '').trim()));
    return !hasText && !hasStem && !hasImg && !hasAns && !hasExp && !hasOpts;
  }
  if (it.t === 'note') return !(it.title || '').trim() && !(it.text || '').trim();
  if (it.t === 'h') return !(it.text || '').trim();
  return false;
};

function fontCss(doc) {
  const fid = (doc && doc.type && doc.type.font) || (doc && doc.font) || 'lora';
  return (FONTS.find(f => f.id === fid) || FONTS[0]).css;
}

function el(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text != null) e.textContent = text;
  return e;
}

function linkInfo(l) {
  if (!l || !l.value) return null;
  const p = PLATFORMS[l.platform] || PLATFORMS.web;
  let url = l.value.trim();
  if (!url.startsWith('http://') && !url.startsWith('https://') && !url.startsWith('mailto:')) {
    if (l.platform === 'mail') url = 'mailto:' + url;
    else if (l.platform === 'instagram') url = 'https://instagram.com/' + url.replace('@', '');
    else if (l.platform === 'x') url = 'https://x.com/' + url.replace('@', '');
    else if (l.platform === 'youtube') url = 'https://youtube.com/' + (url.startsWith('@') ? url : '@' + url);
    else if (l.platform === 'github') url = 'https://github.com/' + url.replace('@', '');
    else if (l.platform === 'telegram') url = 'https://t.me/' + url.replace('@', '');
    else url = 'https://' + url;
  }
  return { name: p.name, icon: p.icon, url, label: l.value };
}

