function newSingleDoc() {
  return {
    id: uid(),
    kind: 'Tek Soru',
    packName: 'Genel Soru Öbeği',
    title: 'Görsel Soru — ' + new Date().toLocaleDateString('tr-TR'),
    updated: Date.now(),
    headerTag: 'TÜRK EDEBİYATI',
    questionText: 'Aşağıdaki dizelerin hangisinde redif kullanılmamıştır?\n\nI. Bizim pencereler __yele karşıdır__\nII. Muhabbet dediğin __kalbe karşıdır__',
    questionStem: 'Buna göre dizelerdeki uyak türü hangisidir?',
    opts: ['Tam Uyak', 'Yarım Uyak', 'Zengin Uyak', 'Cinaslı Uyak', 'Tunç Uyak'],
    hasE: true,
    stemBold: true,
    stemUnderline: true,
    stemColor: '#a8e6cf',
    stemBg: 'transparent',
    correctAnswer: 'A',
    showAnswerBadge: true,
    showSolution: true,
    solutionText: 'Dizelerde "-e karşıdır" redif, "-el" sesleri ise tam uyaktır.',
    image: null,
    imageW: 0,
    imageH: 0,
    aspectRatio: '9:16', // '9:16', '1:1', '4:5', '16:9', '3:4'
    bgType: 'preset',
    bgPreset: 'nature', // 'nature', 'space', 'cinema', 'myth', 'parchment', 'blackboard', 'marble', 'ebru', 'espresso', 'rose', 'kraft'
    bgOpacity: 100, // %10 - %100
    bgOverlayOpacity: 0, // %0 - %80
    customBgImage: null,
    autoFit: true,
    frameStyle: 'selcuk-star', // 'none', 'simple', 'double', 'selcuk', 'gold', 'rounded'
    frameColor: '#56ab2f',
    frameWidth: 2,
    font: 'lora',
    fontSize: 20,
    lineHeight: 1.55,
    textAlign: 'left'
  };
}

/* Tek Seferlik Görsel Kart Oluşturucu */
function renderSingleCard(sDoc, container) {
  container.innerHTML = '';
  const ratio = ASPECT_RATIOS[sDoc.aspectRatio] || ASPECT_RATIOS['9:16'];
  const preset = BG_PRESETS.find(p => p.id === sDoc.bgPreset) || BG_PRESETS[0];

  const card = el('div', 'single-visual-card ratio-' + (sDoc.aspectRatio || '9:16').replace(':', '-'));
  card.dataset.ratio = sDoc.aspectRatio || '9:16';
  card.style.aspectRatio = ratio.cssRatio;
  card.style.fontFamily = fontCss({ type: { font: sDoc.font } });

  // ⚡ Metne ve En-Boy Oranına Göre Otomatik Boyutlandırma (Auto-Fit)
  const ratioScales = {
    '9:16': 1.0,
    '3:4': 0.88,
    '4:5': 0.84,
    '1:1': 0.74,
    '16:9': 0.56
  };
  const rFactor = ratioScales[sDoc.aspectRatio] || 1.0;

  let effectiveFontSize = sDoc.fontSize || 19;
  let effectiveLineHeight = sDoc.lineHeight || 1.55;

  if (sDoc.autoFit !== false) {
    const textLen = (sDoc.questionText || '').length + (sDoc.questionStem || '').length + (sDoc.solutionText || '').length + (sDoc.image ? 140 : 0);
    let lenScale = 1.0;
    if (textLen > 400) lenScale = 0.72;
    else if (textLen > 280) lenScale = 0.80;
    else if (textLen > 180) lenScale = 0.88;
    else if (textLen > 100) lenScale = 0.94;

    effectiveFontSize = Math.max(10.5, Math.round(effectiveFontSize * rFactor * lenScale));
    if (sDoc.aspectRatio === '16:9') {
      effectiveLineHeight = Math.min(1.35, effectiveLineHeight * 0.92);
    }
  }

  card.style.fontSize = effectiveFontSize + 'px';
  card.style.lineHeight = effectiveLineHeight;

  const isDark = (sDoc.bgType === 'preset' && preset.isDark) || sDoc.themeMode === 'light-text';
  card.classList.toggle('theme-dark-bg', isDark);
  card.classList.toggle('theme-light-bg', !isDark);

  // 1. Arka Plan Katmanı
  const bgLayer = el('div', 'single-bg-layer');
  if (sDoc.bgType === 'custom' && sDoc.customBgImage) {
    bgLayer.style.backgroundImage = `url(${sDoc.customBgImage})`;
  } else {
    bgLayer.style.backgroundImage = `url("${preset.dataUri || preset.file}")`;
  }
  const bgOp = (sDoc.bgOpacity != null ? sDoc.bgOpacity : 100) / 100;
  bgLayer.style.opacity = bgOp.toFixed(2);
  card.appendChild(bgLayer);

  // 2. Karartma / Işıltı Örtü Katmanı
  if (sDoc.bgOverlayOpacity > 0) {
    const ov = el('div', 'single-overlay-layer');
    ov.style.backgroundColor = isDark ? '#000' : '#fff';
    ov.style.opacity = (sDoc.bgOverlayOpacity / 100).toFixed(2);
    card.appendChild(ov);
  }

  // 3. Çerçeve Katmanı (20 Türk Kültürü Çerçeve Motifi)
  const frameLayer = el('div', 'single-frame-layer frame-' + (sDoc.frameStyle || 'selcuk-star'));
  frameLayer.innerHTML = buildFrameSvg(sDoc.frameStyle || 'selcuk-star', sDoc.frameColor || preset.defaultBorder, sDoc.frameWidth || 2);
  card.appendChild(frameLayer);

  // 4. İçerik Katmanı
  const content = el('div', 'single-content-layer');
  content.style.textAlign = sDoc.textAlign || 'left';

  // Üst Başlık / Ders Etiketi
  if (sDoc.headerTag && sDoc.headerTag.trim()) {
    const headWrap = el('div', 'single-header-tag-wrap');
    const badge = el('span', 'single-header-tag', sDoc.headerTag.trim().toUpperCase());
    headWrap.appendChild(badge);
    content.appendChild(headWrap);
  }

  // Eklenmiş Görsel
  if (sDoc.image) {
    const imgWrap = el('div', 'single-img-wrap');
    const img = el('img', 'single-q-img');
    img.src = sDoc.image;
    imgWrap.appendChild(img);
    content.appendChild(imgWrap);
  }

  // 1. Soru Metni (Paragraf & Öncül)
  if (sDoc.questionText && sDoc.questionText.trim()) {
    const bodyText = el('div', 'single-q-body');
    bodyText.innerHTML = formatQText(sDoc.questionText, sDoc.stemColor || preset.defaultStem);
    content.appendChild(bodyText);
  }

  // 2. Soru Kökü (KOYU YAZILIR - Belgede ve Kartta Vurgulanır)
  if (sDoc.questionStem && sDoc.questionStem.trim()) {
    const stemWrap = el('div', 'single-stem-wrap');
    const stem = el('div', 'single-stem-text');
    stem.style.fontWeight = '800';
    stem.style.fontSize = '1.05em';
    stem.style.color = sDoc.stemColor || preset.defaultStem;
    stem.style.margin = '10px 0 12px';
    stem.style.lineHeight = '1.45';
    stem.innerHTML = formatQText(sDoc.questionStem.trim(), sDoc.stemColor || preset.defaultStem);
    stemWrap.appendChild(stem);
    content.appendChild(stemWrap);
  }

  // 3. Şıklar (A, B, C, D, E)
  if (sDoc.opts && Array.isArray(sDoc.opts) && sDoc.opts.some(o => (o || '').trim())) {
    const optsWrap = el('div', 'single-opts-wrap');
    const maxOpts = (sDoc.hasE === false) ? 4 : 5;
    for (let i = 0; i < maxOpts; i++) {
      if (!(sDoc.opts[i] || '').trim()) continue;
      const optLine = el('div', 'single-opt-item');
      const optBadge = el('b', 'single-opt-badge', LETTERS[i] + ')');
      optLine.appendChild(optBadge);
      optLine.append(' ' + sDoc.opts[i]);
      optsWrap.appendChild(optLine);
    }
    content.appendChild(optsWrap);
  }



  // Zarif Pıtrak Filigranı
  const brandWatermark = el('div', 'single-card-brand', 'Pıtrak Nüsha');
  content.appendChild(brandWatermark);

  card.appendChild(content);
  container.appendChild(card);
  return card;
}

/* ============================================================ */
/* ÇOKLU SAYFA SAYFALAMA MOTORU (Soru Bankası & Notlar)         */
/* ============================================================ */
function pageShell(doc, container, state) {
  const [w, h] = PAGES[doc.layout.page] || PAGES.A4;
  const p = el('div', 'page');
  p.style.width = w + 'mm';
  p.style.height = h + 'mm';
  p.style.padding = doc.layout.margin + 'mm';
  p.style.setProperty('--ff', fontCss(doc));
  p.style.setProperty('--fs', doc.type.size + 'pt');
  p.style.setProperty('--fg', doc.type.color);
  p.style.setProperty('--accent', doc.type.accent);
  p.style.setProperty('--lh', doc.type.leading);
  p.style.setProperty('--qgap', doc.type.qGap + 'mm');

  if (doc.watermark && doc.watermark.enabled) {
    const wm = el('div', 'wm');
    wm.style.setProperty('--wm-op', (doc.watermark.opacity / 100).toFixed(2));
    wm.style.setProperty('--wm-deg', (doc.watermark.angle || 0) + 'deg');
    if (doc.watermark.kind === 'image' && doc.watermark.image) {
      const im = el('img', 'wm-img');
      im.src = doc.watermark.image;
      if (doc.watermark.imageWidth) im.style.width = doc.watermark.imageWidth + '%';
      wm.appendChild(im);
    } else {
      const t = el('span', 'wm-txt', doc.watermark.text || 'PITRAK NÜSHA');
      t.style.setProperty('--wm-fs', (doc.watermark.size || 26) + 'pt');
      t.style.color = doc.watermark.color || doc.type.accent;
      wm.appendChild(t);
    }
    p.appendChild(wm);
  }
  return p;
}

function coverPage(doc, container, state) {
  const p = pageShell(doc, container, state);
  p.classList.add('cover-page');
  const C = doc.cover;
  if (C.mode === 'image' && C.image) {
    const bg = el('div', 'cover-bg-img'); bg.style.backgroundImage = `url(${C.image})`; p.appendChild(bg);
  } else {
    p.style.backgroundColor = C.bg || '#6b4426';
    p.style.color = C.fg || '#fbf4e8';
  }
  if (C.mode !== 'image' || C.showText) {
    const wrap = el('div', 'cover-content');
    const t = el('h1', 'cover-title', C.title || doc.title || 'Başlık');
    wrap.appendChild(t);
    if (C.subtitle) wrap.appendChild(el('div', 'cover-sub', C.subtitle));
    const authorVal = C.author || doc.author || ''; if (authorVal) wrap.appendChild(el('div', 'cover-author', authorVal));
    const foot = el('div', 'cover-foot');
    foot.appendChild(el('span', 'cover-brand', 'Pıtrak Nüsha'));
    foot.appendChild(el('span', 'cover-kind', doc.kind || 'Soru Bankası'));
    wrap.appendChild(foot);
    p.appendChild(wrap);
  }
  container.appendChild(p);
  state.pages.push(p);
  return p;
}

function contentPage(doc, container, cols, state) {
  const p = pageShell(doc, container, state);
  p.classList.add('content-page');
  const L = doc.layout;

  // Üst Bilgi
  if (L.headerText) {
    const h = el('div', 'phead ' + (L.hfAlign || 'center'));
    h.textContent = L.headerText;
    p.appendChild(h);
  }

  // Gövde & Sütunlar
  const b = el('div', 'pbody ' + (cols === 2 ? 'cols-2' : 'cols-1'));
  const colEls = [];

  // 2 Sütun ve Dikey Çizgi Durumu (Ortadaki Çizgiye Asla Değmez)
  if (cols === 2 && L.rule) {
    b.classList.add('has-rule');

    // 1. Sütun
    const c0 = el('div', 'col');
    if (L.colHeader) c0.appendChild(el('div', 'col-head', L.colHeader));
    colEls.push(c0);
    b.appendChild(c0);

    // Dikey Ayırıcı Çizgi (Estetik desenli, rengi ve stili ayarlanabilir)
    const divRule = el('div', 'col-divider rule-' + (L.ruleStyle || 'double'));
    divRule.style.setProperty('--rule-color', L.ruleColor || '#b98a4a');
    b.appendChild(divRule);

    // 2. Sütun
    const c1 = el('div', 'col');
    if (L.colHeader) c1.appendChild(el('div', 'col-head', L.colHeader));
    colEls.push(c1);
    b.appendChild(c1);
  } else {
    for (let i = 0; i < cols; i++) {
      const c = el('div', 'col');
      if (L.colHeader) c.appendChild(el('div', 'col-head', L.colHeader));
      colEls.push(c);
      b.appendChild(c);
    }
  }
  p.appendChild(b);

  // Alt Bilgi ve Sayfa Numarası
  if (L.footerText || L.pageNum !== 'none') {
    const f = el('div', 'pfoot ' + (L.hfAlign || 'center'));
    if (L.footerText) f.appendChild(el('span', 'pfoot-txt', L.footerText));
    if (L.pageNum !== 'none') {
      const pn = el('span', 'pfoot-num pnum-' + L.pageNum);
      pn.dataset.pn = '1';
      f.appendChild(pn);
    }
    p.appendChild(f);
  }

  container.appendChild(p);
  state.pages.push(p);
  return { p, cols: colEls };
}

/* Soru Bloku */
function qBlock(doc, q, no, withAns) {
  const L = doc.layout, d = el('div', 'q');
  const t = el('div', 'qtxt');
  const numLabel = L.numStyle === 'Soru 1.' ? 'Soru ' + no + '.' : L.numStyle === '1)' ? no + ')' : no + '.';
  
  const rawText = (q.text || '').trim();
  const stemColor = (doc.type && doc.type.stemColor) || (doc.type && doc.type.accent) || '#6b4426';
  
  // formatQText ile [[ ]] ve __ biçimlendirilir
  const formattedHtml = formatQText(rawText, stemColor);
  t.innerHTML = `<b class="qno">${numLabel}</b> ` + (formattedHtml || ' ');
  d.appendChild(t);

  // Soru Kökü (2. Pencereden gelen soru kökü - Belgede Koyu Yazılır)
  if (q.stem && q.stem.trim()) {
    const stm = el('div', 'qtxt-stem');
    stm.style.fontWeight = '800';
    stm.style.color = stemColor;
    stm.style.marginTop = '6px';
    stm.style.marginBottom = '6px';
    stm.style.lineHeight = '1.45';
    stm.innerHTML = formatQText(q.stem.trim(), stemColor);
    d.appendChild(stm);
  }

  if (q.image) {
    const i = el('img', 'qimg');
    i.src = q.image;
    if (q.w) { i.width = q.w; i.height = q.h; }
    d.appendChild(i);
  }

  // Şıklar (varsa)
  if (q.opts && q.opts.some(o => (o || '').trim())) {
    const o = el('div', 'opts');
    const maxOpts = (q.hasE === false) ? 4 : (L.optCount || 5);
    for (let i = 0; i < maxOpts; i++) {
      if (!(q.opts[i] || '').trim() && !(i < 2)) continue;
      const r = el('div', 'opt');
      r.appendChild(el('b', '', L.optStyle === 'A.' ? LETTERS[i] + '.' : L.optStyle === '(A)' ? '(' + LETTERS[i] + ')' : LETTERS[i] + ')'));
      r.append(' ' + (q.opts[i] || ''));
      o.appendChild(r);
    }
    d.appendChild(o);
  }

  if (withAns && ((q.answer || '').trim() || (q.explain || '').trim())) {
    const a = el('div', 'ans');
    a.textContent = 'Doğru Cevap: ' + (q.answer || '—') + (q.explain ? ' · Çözüm: ' + q.explain : '');
    d.appendChild(a);
  }
  return d;
}

/* Ders Notu Bloku */
function noteBlock(doc, note) {
  const d = el('div', 'note-card ' + (note.style || 'info'));
  const styleLabels = {
    info: '📌 Konu Notu / Önemli',
    warn: '⚠️ Dikkat / Uyarı',
    def: '📖 Tanım & Kavram',
    example: '💡 Çözümlü Örnek',
    formula: '📐 Formül / Kural'
  };
  const headText = note.title ? note.title : styleLabels[note.style] || 'Not';
  const h = el('div', 'note-card-head', headText);
  d.appendChild(h);
  if (note.text) {
    const b = el('div', 'note-card-body');
    note.text.split('\n').filter(s => s.trim()).forEach(p => {
      b.appendChild(el('p', '', p.trim()));
    });
    d.appendChild(b);
  }
  return d;
}

function headingBlock(h) {
  const d = el('div', 'sect-head');
  d.appendChild(el('h3', 'sect-title', h.text || 'Bölüm'));
  return d;
}

/* Şık Cevap Anahtarı Tablosu */
function answerKeyTableBlock(doc, qs) {
  const L = doc.layout || {};
  const wrap = el('div', 'ans-table-section');
  
  const titleWrap = el('div', 'ans-table-header-wrap');
  const title = el('div', 'ans-table-title', 'CEVAP ANAHTARI');
  titleWrap.appendChild(title);
  wrap.appendChild(titleWrap);

  const groupSize = L.answerKeyCols || 5;
  const table = el('table', 'ans-key-table');
  if (L.answerKeyFontSize) {
    table.style.fontSize = L.answerKeyFontSize + 'pt';
  }

  const thead = el('thead');
  const headRow = el('tr');
  for (let g = 0; g < groupSize; g++) {
    headRow.appendChild(el('th', 'th-no', 'Soru'));
    headRow.appendChild(el('th', 'th-ans', 'Cevap'));
  }
  thead.appendChild(headRow);
  table.appendChild(thead);

  const tbody = el('tbody');
  const rowCount = Math.ceil(qs.length / groupSize);

  for (let r = 0; r < rowCount; r++) {
    const tr = el('tr');
    for (let c = 0; c < groupSize; c++) {
      const idx = r + c * rowCount;
      if (idx < qs.length) {
        const item = qs[idx];
        const tdNo = el('td', 'td-no', item.no + '.');
        const ansVal = (item.q.answer || '—').trim();
        const tdAns = el('td', 'td-ans' + (ansVal !== '—' ? ' ans-filled' : ''), ansVal);
        tr.appendChild(tdNo);
        tr.appendChild(tdAns);
      } else {
        tr.appendChild(el('td', 'td-no empty-cell', ''));
        tr.appendChild(el('td', 'td-ans empty-cell', ''));
      }
    }
    tbody.appendChild(tr);
  }
  table.appendChild(tbody);
  wrap.appendChild(table);
  return wrap;
}

/* Şık Ayrıntılı Çözümler Bölümü */
function solutionsSectionBlock(doc, qsWithSol) {
  const L = doc.layout || {};
  const wrap = el('div', 'solutions-section');

  const titleWrap = el('div', 'solutions-header-wrap');
  const title = el('div', 'solutions-title', '✦ AYRINTILI ÇÖZÜMLER ✦');
  titleWrap.appendChild(title);
  wrap.appendChild(titleWrap);

  const list = el('div', 'solutions-list');
  if (L.solutionsFontSize) list.style.fontSize = L.solutionsFontSize + 'pt';
  if (L.solutionsLineHeight) list.style.lineHeight = L.solutionsLineHeight;

  qsWithSol.forEach(({ q, no }) => {
    const card = el('div', 'solution-item');
    const head = el('div', 'solution-item-head');
    head.appendChild(el('span', 'sol-no-badge', no + '. Soru Çözümü'));
    if ((q.answer || '').trim()) {
      head.appendChild(el('span', 'sol-ans-badge', 'Doğru Cevap: ' + q.answer.trim()));
    }
    card.appendChild(head);

    const body = el('div', 'solution-item-body');
    (q.explain || '').split('\n').filter(s => s.trim()).forEach(para => {
      body.appendChild(el('p', 'sol-p', para.trim()));
    });
    card.appendChild(body);
    list.appendChild(card);
  });

  wrap.appendChild(list);
  return wrap;
}

/* Sayfa Akış Motoru */
function makeFlow(doc, container, state, cols, forceSingleCol = false) {
  let cur = null, colIdx = 0;
  const colCount = forceSingleCol ? 1 : cols;
  function nextCol() {
    if (!cur || colIdx >= colCount - 1) {
      cur = contentPage(doc, container, colCount, state);
      colIdx = 0;
    } else {
      colIdx++;
    }
    return cur.cols[colIdx];
  }
  let target = nextCol();

  return {
    put(node) {
      target.appendChild(node);
      const host = cur.p.querySelector('.pbody');
      if (host.scrollHeight > host.clientHeight + 2) {
        target.removeChild(node);
        target = nextCol();
        target.appendChild(node);
      }
    },
    brk() {
      cur = contentPage(doc, container, colCount, state);
      colIdx = 0;
      target = cur.cols[0];
    }
  };
}

function prefacePages(doc, container, state) {
  const P = doc.preface, flow = makeFlow(doc, container, state, 1, true);
  const t = el('div', 'pref-title', P.title || 'Önsöz'); flow.put(t);
  (P.text || '').split(/\n{1,}/).filter(s => s.trim()).forEach(s => flow.put(el('p', 'pref-p', s.trim())));
  if (P.signature) flow.put(el('div', 'pref-sign', P.signature));
  const links = (P.links || []).map(linkInfo).filter(Boolean);
  if (links.length) {
    const row = el('div', 'sm-row');
    links.forEach(l => { const a = el('a', 'sm-link'); a.href = l.url; a.dataset.url = l.url; a.target = '_blank'; a.rel = 'noopener'; a.append(el('b', '', l.name), ' ' + l.label); row.appendChild(a); });
    flow.put(row);
  }
}

/* Ana üretici: tüm sayfaları container içine kurar */
function buildDoc(doc, container) {
  container.innerHTML = '';
  const state = { pages: [] };
  if (doc.cover && doc.cover.enabled) coverPage(doc, container, state);
  if (doc.preface && doc.preface.enabled) prefacePages(doc, container, state);
  state.contentStart = state.pages.length;
  const cols = doc.layout.columns, flow = makeFlow(doc, container, state, cols);

  let no = 0, pendingH = null; const qs = [];
  doc.items.forEach(it => {
    if (it.t === 'h') { pendingH = it; return; }
    if (isBlank(it)) return;
    const b = el('div', 'blk');
    if (pendingH) { b.appendChild(headingBlock(pendingH)); pendingH = null; }
    
    if (it.t === 'note') {
      b.appendChild(noteBlock(doc, it));
    } else {
      no++; qs.push({ q: it, no });
      b.appendChild(qBlock(doc, it, no, doc.layout.answers === 'inline'));
    }
    flow.put(b);
  });
  if (pendingH) flow.put(headingBlock(pendingH));

  // Cevap Anahtarı Tablosu Ekle
  const hasAnswerKey = qs.length && (doc.layout.showAnswerKey !== false);
  if (hasAnswerKey) {
    if (doc.layout.answerKeyNewPage) flow.brk();
    flow.put(answerKeyTableBlock(doc, qs));
  }

  // Ayrıntılı Çözümler Bölümü Ekle
  const qsWithSol = qs.filter(x => (x.q.explain || '').trim().length > 0);
  const hasSolutions = qsWithSol.length && (doc.layout.showSolutions !== false);
  if (hasSolutions) {
    if (doc.layout.solutionsNewPage) flow.brk();
    flow.put(solutionsSectionBlock(doc, qsWithSol));
  }

  if (!state.pages.length || (state.pages.length === state.contentStart && !doc.items.length)) {
    const c = contentPage(doc, container, cols, state);
    const msg = doc.kind === 'Ders Notu' 
      ? 'Henüz not eklenmedi. Yukarıdaki butonlardan ilk konunu veya özetini yazarak başla.' 
      : 'Henüz soru eklenmedi. Yukarıdaki butondan ilk sorunu yazarak başla.';
    const e = el('div', 'empty-note', msg); c.cols[0].appendChild(e);
  }
  let n = 0;
  state.pages.forEach((p, i) => { if (i >= state.contentStart) { n++; p.querySelectorAll('[data-pn]').forEach(e => e.textContent = n); } });
  return state.pages;
}

/* Tek soru kartı */
function buildSingle(doc, q, no, withAns) {
  const w = el('div', 'single');
  w.style.setProperty('--ff', fontCss(doc)); w.style.setProperty('--fs', doc.type.size + 'pt');
  w.style.setProperty('--fg', doc.type.color); w.style.setProperty('--accent', doc.type.accent); w.style.setProperty('--lh', doc.type.leading);
  w.appendChild(qBlock(doc, q, no, withAns));
  return w;
}

window.buildDoc = buildDoc;
window.buildSingle = buildSingle;
window.newDoc = newDoc;
window.newQuestion = newQuestion;
window.newNote = newNote;
window.newHeading = newHeading;
window.newSingleDoc = newSingleDoc;
window.renderSingleCard = renderSingleCard;
window.formatQText = formatQText;
window.buildFrameSvg = buildFrameSvg;
window.buildFrameMiniThumb = buildFrameMiniThumb;
window.FRAME_CATALOG = FRAME_CATALOG;
window.ASPECT_RATIOS = ASPECT_RATIOS;
window.BG_PRESETS = BG_PRESETS;
window.FONTS = FONTS;
